<span class="line"><span style="color:#D73A49;">        let</span><span style="color:#24292E;"> endTime </span><span style="color:#D73A49;">=</span><span style="color:#D73A49;"> new</span><span style="color:#6F42C1;"> Date</span><span style="color:#24292E;">().</span><span style="color:#6F42C1;">getTime</span><span style="color:#24292E;">() </span><span style="color:#D73A49;">+</span><span style="color:#24292E;"> time </span><span style="color:#D73A49;">*</span><span style="color:#005CC5;"> 1000</span><span style="color:#24292E;">;</span></span>
